const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

app.get('/api/warehouses/audits/:auditId/aggregate', async (req, res) => {
  if (!req.user || !req.user.warehouseId) {
    return res.status(401).json({ error: 'Warehouse authorization required' });
  }

  // Explicitly inject warehouseId boundary into aggregate query filter
  const stats = await prisma.inventoryAudit.aggregate({
    where: {
      id: req.params.auditId,
      warehouseId: req.user.warehouseId
    },
    _sum: { missingUnits: true, damagedValueUsd: true }
  });

  res.json({ auditId: req.params.auditId, stats });
});

app.listen(3039);
